-- evt:offering_1
RegisterEvent(12, "Offering", function()
    if not (IsQBitSet(QBit(110047)) and IsAtLeast(MapVar(3), 0) and not IsAtLeast(MapVar(3), 1)) then
        if IsQBitSet(QBit(110047)) then
            evt.StatusText("The statue's hands are empty.")
        else
            evt.DamagePlayer(Players.All, const.Damage.Air, 30)
            evt.SimpleMessage("A gust of wind strikes you from the statue's hands. It is kept for Crusaders.")
        end
        return
    end
    SetValue(MapVar(3), 1)
    evt.GiveItem(3, 0)
    evt.StatusText("The statue's open hands hold a gift for a Crusader.", 5)
end, "Offering")

